import{d as b,C as t,o as c,c as m,j as a,a as s,E as r,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第八十章","description":"从小国寡民读什伯之器、重死安居与复结绳，保留返古治理理想及其边界。","frontmatter":{"title":"道德经第八十章","description":"从小国寡民读什伯之器、重死安居与复结绳，保留返古治理理想及其边界。","category":"guide","aliases":["道德经第八十章","老子第八十章","dao de jing chapter 80"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-80.md","filePath":"daoism/dao-de-jing/chapter-80.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-80.md"},y=b({...g,setup(p){const o=[{id:"small-state-and-few-people",label:"小国寡民",showLabel:!0,sentences:[["小国",{text:"寡",glossary:"gua-humble"},"民。"]],note:["【白话】国家小，人民少。本章从这样的国民规模起笔，提出接下来的简朴安居图景。","【王弼注择要】「国既小，民又寡，尚可使反古，况国大民众乎？故举小国而言也。」","【读法】王注把举小国连到反古之意，并认为国大民众也可由此推想；不能只因标题而说王弼将所有主张限定为小国适用，也不抹去正文的小国寡民。"]},{id:"tools-without-demand-for-use",label:"使有什伯之器而不用",showLabel:!0,sentences:[["使有",{text:"什伯",glossary:"shibai"},"之器而不用，"]],note:["【白话】使人们即使拥有能发挥十倍百倍功效的器具，也不必使用。什伯之器先采用常见的倍数训法，具体器物所指仍有分歧。","【王弼注择要】「言使民虽有什伯之器而无所用之，当何患不足也。」","【读法】汉典什、伯条分别列本章为十倍、百倍的例句；伯通百读 bǎi。另有按军用器具等解释的路向，王注此处未逐字定训，不能把倍数释义说成王弼的明确原话。"]},{id:"valuing-life-and-staying-home",label:"使民重死而不远徙",showLabel:!0,sentences:[["使民",{text:"重",glossary:"zhong-weight"},"死而不远",{text:"徙",glossary:"xi-migrate"},"。"]],note:["【白话】使百姓慎重对待死亡、珍惜生命，不向远处迁徙。这句把不远行迁居与重死连在一起。","【王弼注择要】「惟身是宝，不贪货赂，故各安其居，重死而不远徙也。」","【读法】重读 zhòng，不是让人更常面对死亡。注中以珍重自身、不贪货赂说明安居；不能将原文直接改成现代自由迁徙政策，也不把不远徙解释为禁迁的条文。"]},{id:"boats-and-arms-without-use",label:"虽有舟舆，无所乘之",showLabel:!0,sentences:[["虽有",{text:"舟舆",glossary:"zhouyu-transport"},"，无所乘之；虽有",{text:"甲兵",glossary:"jiabing-arms"},"，无所",{text:"陈",glossary:"chen-deploy"},"之。"]],note:["【白话】虽然有船车，却没有需要乘用的地方；虽然有兵甲，却没有需要部署列阵的地方。交通与兵备都在，却无所施用。","【读法】经文强调有而不用，不是以物资匮乏作为安居前提。王注在这两句后未另作逐句解释，不补造它赞同某项现代技术或交通政策的结论。"]},{id:"returning-to-knotted-cords",label:"使民复结绳而用之",showLabel:!0,sentences:[["使民复",{text:"结绳",glossary:"jiesheng"},"而用之。"]],note:["【白话】使百姓重新使用结绳记事。复是返回，结绳将前面简朴少求的设想推进到返古的记事方式。","【读法】本站使民复，所据作使人复，保留现文并列差异。使民的治理立场与返古倾向应如实呈现，不软化成只是个人偶尔放下手机。"]},{id:"contentment-in-daily-life",label:"甘其食，美其服",showLabel:!0,sentences:[[{text:"甘",glossary:"gan-find-sweet"},"其食，",{text:"美",glossary:"mei-praise"},"其服，安其居，",{text:"乐",glossary:"le-glad"},"其俗。"]],note:["【白话】觉得自己的食物甘美、衣服美好，安于自己的居处，乐于自己的风俗。四句连写食、服、居、俗的满足。","【读法】甘、美、安、乐在这里均可按以为甘美安乐理解；说的是对生活的感受与安处，不只是客观上食物甜、衣服华贵。满足的现代讨论仍需与基本生活保障分开。"]},{id:"nearby-states-without-travel",label:"邻国相望",showLabel:!0,sentences:[["邻国相望，鸡犬之声相闻，民至老死不相往来。"]],note:["【白话】相邻的国家彼此看得见，鸡鸣犬吠彼此听得到，百姓却直到老死也不互相往来。结尾用近在咫尺却不往来的形象，完成这一安居理想。","【王弼注择要】结尾下注「无所欲求」。","【读法】依注，重心是不再向外欲求；但正文确实写终身不相往来，不能改成仅仅减少无效社交。今天可以讨论知足与在地生活，也要另辨开放交流、个人选择与被限制流动。"]}],n=[{id:"gua-humble",term:"寡",sense:2},{id:"shibai",term:"什伯",sense:1},{id:"zhong-weight",term:"重",sense:3},{id:"xi-migrate",term:"徙",sense:1},{id:"zhouyu-transport",term:"舟舆",sense:1},{id:"jiabing-arms",term:"甲兵",sense:1},{id:"chen-deploy",term:"陈",sense:1},{id:"jiesheng",term:"结绳",sense:1},{id:"gan-find-sweet",term:"甘",sense:1},{id:"mei-praise",term:"美",sense:1},{id:"le-glad",term:"乐",sense:3}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第八十章",tabindex:"-1"},[s("道德经第八十章 "),a("a",{class:"header-anchor",href:"#道德经第八十章","aria-label":'Permalink to "道德经第八十章"'},"​")],-1)),r(i,{title:"器物俱在而不用，描画怎样的安居理想",summary:"本章提出小国寡民的理想图景：有器而不用，重死不远徙，舟舆甲兵无所施，复用结绳，并以甘食、美服、安居、乐俗收束。邻国可望闻，却终老不相往来，是原文鲜明的返古设想。王注以无所欲求解释结尾，现代相参仍需辨清选择与限制。",points:[{label:"先读",text:"有器而不用不等于没有器物，先看不用怎样与安居相连。"},{label:"再辨",text:"什伯的常见训法与王注分别说明；重死指慎死惜生。"},{label:"后看",text:"保留复结绳、不往来的原文理想，再讨论今天如何理解。"}],hint:"什伯读 shí bǎi，重死读 zhòng sǐ，徙读 xǐ，舟舆读 zhōu yú；乐其俗的乐读 lè。甘、美、安、乐连用，指以自己的食服居俗为甘美安乐。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:o,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"使有什伯之器而不用，使民重死而不远徙。",tone:"有而不用与惜生安居",guide:"器物是否存在，与是否必须动用，是两层问题。"},{text:"甘其食，美其服，安其居，乐其俗。",tone:"让生活可安可乐",guide:"食服居俗四面连读，不只是一句降低欲望。"},{text:"民至老死不相往来。",tone:"直面理想的距离",guide:"先承认原文图景，再分开讨论现代选择。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=u("",15))])}}});export{_ as __pageData,y as default};
